import org.springframework.web.servlet.handler.HandlerInterceptor;
import org.springframework.web.servlet.support.RequestContextUtils;

public class ThrottleRequestFilter implements HandlerInterceptor {
    private static final int MAX_REQUESTS_PER_MINUTE = 10;
    private static final long EXPIRATION_TIME = 60 * 1000; // 1 minute

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws Exception {
        RequestContextUtils.getWebRequest(request).getHeaders().remove("X-Original-IP");
        RateLimiter rateLimiter = new RateLimiter(MAX_REQUESTS_PER_MINUTE, EXPIRATION_TIME);
        if (rateLimiter.isRateLimited()) {
            response.setStatus(HttpServletResponse.SC_TOO_MANY_REQUESTS);
            return false;
        }
        return true;
    }
}
```

